def predict(history, action):
    grid = np.array(history.frames[-1], dtype=np.int8)
    kind = int(action.kind)
    if kind == 6:
        row = int(action.row)
        col = int(action.col)
        # ACTION6: Interact with the grid at (row, col)
        # Check if the cell is empty (0) or a wall (5) or player (9) or goal (14)
        val = grid[row, col]
        if val == 0:
            # Move into empty space
            grid[row, col] = 9
        elif val == 5:
            # Hit a wall, stay put
            pass
        elif val == 9:
            # Stay on player
            pass
        elif val == 14:
            # Reached goal
            grid[row, col] = 0
    return {"next_grid": grid, "game_state": "WIN" if kind == 6 and action.row is not None and action.col is not None else "NOT_FINISHED", "level_delta": 1 if kind == 6 and action.row is not None and action.col is not None else 0, "memory": {}}

def goal_value(history):
    last_frame = history.frames[-1]
    # Check for presence of goal value 14 (green)
    if 14 in last_frame:
        return 1.0
    return 0.0

def predict(history, action):
    kind = int(action.kind)
    grid = np.array(history.frames[-1], dtype=np.int8)
    next_grid = grid.copy()

    if kind == 6:
        if action.row is not None and action.col is not None:
            row, col = action.row, action.col
            if grid[row, col] == 14:
                next_grid[row, col] = 0
                next_grid[row, col+1] = 14
                next_grid[row+1, col] = 14
    elif kind == 1:
        # ACTION1: Move left
        if np.any(grid == 14):
            pos = np.argwhere(grid == 14)
            if len(pos) > 0:
                r, c = pos[0]
                if c > 0 and grid[r, c-1] != 14:
                    next_grid[r, c] = 0
                    next_grid[r, c-1] = 14
    elif kind == 2:
        # ACTION2: Move up
        if np.any(grid == 14):
            pos = np.argwhere(grid == 14)
            if len(pos) > 0:
                r, c = pos[0]
                if r > 0 and grid[r-1, c] != 14:
                    next_grid[r, c] = 0
                    next_grid[r-1, c] = 14
    elif kind == 3:
        # ACTION3: Move right
        if np.any(grid == 14):
            pos = np.argwhere(grid == 14)
            if len(pos) > 0:
                r, c = pos[0]
                if c < 63 and grid[r, c+1] != 14:
                    next_grid[r, c] = 0
                    next_grid[r, c+1] = 14
    elif kind == 4:
        # ACTION4: Move down
        if np.any(grid == 14):
            pos = np.argwhere(grid == 14)
            if len(pos) > 0:
                r, c = pos[0]
                if r < 63 and grid[r+1, c] != 14:
                    next_grid[r, c] = 0
                    next_grid[r+1, c] = 14

    game_state = "WIN" if np.sum(next_grid) == 0 else "NOT_FINISHED"
    return {"next_grid": next_grid, "game_state": game_state, "level_delta": 0, "memory": {}}

def goal_value(history):
    last_frame = history.frames[-1]
    if last_frame is None:
        return 0.0
    grid_values = last_frame.get("grid_values", [])
    return 0.0 if len(grid_values) == 0 else 1.0
